using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B1DeskFinish {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B1_InteriorRedesign/";static string O=>R+"/Docs/Review/2026-11-12_B1_DeskProps/";const string E="Assets/Afrer_Seconds/05.Model/Environment/B1/";
 static void Check(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty||!SceneManager.GetActiveScene().path.EndsWith("Level_B1_Circular.unity"))throw new Exception("Saved B1 required");}
 public static object Reflections(){Check();var s=SceneManager.GetActiveScene();var root=GameObject.Find("B1_ResearchAndStaffFloor").transform;var parent=root.Find("B1_Reflections");var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool enabled=player.activeSelf;player.SetActive(false);int n=0;
  var points=new System.Collections.Generic.Dictionary<string,Vector2>{{"C01",new Vector2(0,-1.1f)},{"C02",new Vector2(2.8f,1)},{"C03",new Vector2(0,-1.4f)},{"C04",new Vector2(0,-1.4f)},{"C05",new Vector2(0,-2.4f)},{"W01",new Vector2(0,1.6f)},{"W02",new Vector2(1,2.6f)},{"W03",new Vector2(-3.4f,.9f)},{"E01",new Vector2(0,-.5f)},{"E02",new Vector2(3,-1.2f)},{"E03",new Vector2(-3.4f,.9f)},{"N01",new Vector2(0,-.5f)},{"S01",new Vector2(0,-1.4f)}};
  try{foreach(var r in JObject.Parse(File.ReadAllText(H+"layout.json"))["rooms"]){string id=(string)r["id"];var tr=parent.Find("Reflection_"+id);if(!tr)throw new Exception("Existing probe missing");var pr=tr.GetComponent<ReflectionProbe>();float rad=(float)r["r"];if(points.TryGetValue(id,out var v)){tr.localPosition=new Vector3((float)r["x"]+v.x,2,-(float)r["v"]+v.y);pr.center=new Vector3(-v.x,rad*.5f-2,-v.y);}string file=E+"Textures/BL_Reflection_"+id+".exr";if(!Lightmapping.BakeReflectionProbe(pr,file))throw new Exception("Probe bake failed "+id);AssetDatabase.ImportAsset(file,ImportAssetOptions.ForceSynchronousImport);pr.customBakedTexture=AssetDatabase.LoadAssetAtPath<Cubemap>(file);n++;}}finally{player.SetActive(enabled);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);AssetDatabase.SaveAssets();var result=new{probes=n,repositioned=points.Count};File.WriteAllText(O+"reflections.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
 public static object Bake(){Check();if(StaticOcclusionCulling.isRunning)throw new Exception("Already baking");StaticOcclusionCulling.smallestHole=.05f;var s=SceneManager.GetActiveScene();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);StaticOcclusionCulling.GenerateInBackground();return new{running=StaticOcclusionCulling.isRunning};}
 public static object Status(){var r=new{running=StaticOcclusionCulling.isRunning,bytes=StaticOcclusionCulling.umbraDataSize,smallestHole=StaticOcclusionCulling.smallestHole};if(!r.running){var s=SceneManager.GetActiveScene();if(s.isDirty)EditorSceneManager.SaveScene(s);File.WriteAllText(O+"occlusion.json",JsonConvert.SerializeObject(r,Formatting.Indented));}return r;}
 public static object Close(){Check();if(StaticOcclusionCulling.isRunning)throw new Exception("Bake not finished");Selection.activeGameObject=GameObject.Find("B1_C01_Data_ResearchDesk_01");var v=SceneView.lastActiveSceneView;if(v){v.sceneLighting=true;v.LookAt(Selection.activeGameObject.transform.position+new Vector3(0,1,.08f),Quaternion.Euler(30,180,0),1.1f,false,true);v.Focus();v.Repaint();}var r=new{saved=!SceneManager.GetActiveScene().isDirty,playing=Application.isPlaying,scene=SceneManager.GetActiveScene().path,selection=Selection.activeGameObject.name,mouseEnabled=UnityEngine.InputSystem.Mouse.current.enabled,keyboardEnabled=UnityEngine.InputSystem.Keyboard.current.enabled,runInBackground=Application.runInBackground,occlusionRunning=StaticOcclusionCulling.isRunning};File.WriteAllText(O+"final_state.json",JsonConvert.SerializeObject(r,Formatting.Indented));return r;}
}
